import{_ as t,c as i,o as a,ag as n}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"Creating an Intellipedia Page for a TAAW","description":"","frontmatter":{"title":"Creating an Intellipedia Page for a TAAW"},"headers":[],"relativePath":"general/creating-an-intellipedia-page-for-a-taaw.md","filePath":"general/creating-an-intellipedia-page-for-a-taaw.md","lastUpdated":null}'),o={name:"general/creating-an-intellipedia-page-for-a-taaw.md"};function l(r,e,s,h,d,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="creating-an-intellipedia-page-for-a-taaw" tabindex="-1">Creating an Intellipedia Page for a TAAW <a class="header-anchor" href="#creating-an-intellipedia-page-for-a-taaw" aria-label="Permalink to &quot;Creating an Intellipedia Page for a TAAW&quot;">​</a></h1><h2 id="intellipedia-workflow-creating-an-intellipedia-page-for-a-taaw" tabindex="-1">Intellipedia Workflow: Creating an Intellipedia Page for a TAAW <a class="header-anchor" href="#intellipedia-workflow-creating-an-intellipedia-page-for-a-taaw" aria-label="Permalink to &quot;Intellipedia Workflow: Creating an Intellipedia Page for a TAAW&quot;">​</a></h2><h3 id="step-1-search-for-your-refined-target-audience" tabindex="-1">Step 1: Search for Your Refined Target Audience <a class="header-anchor" href="#step-1-search-for-your-refined-target-audience" aria-label="Permalink to &quot;Step 1: Search for Your Refined Target Audience&quot;">​</a></h3><p>Search your refined target audience for the page you wish to create in the search bar.</p><p><strong>Example:</strong> U.S. Citizens 18-25 that attend AC/DC concerts in City X, Country Y</p><ul><li>Intellipedia will prompt the user to create a page that does not exist. This will show up as red text.</li><li>Click the link to create the page.</li></ul><h3 id="step-2-select-create-view" tabindex="-1">Step 2: Select Create View <a class="header-anchor" href="#step-2-select-create-view" aria-label="Permalink to &quot;Step 2: Select Create View&quot;">​</a></h3><p>Ensure that you are in the <em>Create</em> view and not the <em>Create Source</em> view in the top right below your username.</p><h3 id="step-3-add-heading" tabindex="-1">Step 3: Add Heading <a class="header-anchor" href="#step-3-add-heading" aria-label="Permalink to &quot;Step 3: Add Heading&quot;">​</a></h3><p>Use heading font with this formula (see <a href="https://socom.sharepoint-mil.us/sites/socsouth-j3-jedpsyop/SiteAssets/SOCSOUTH%20J39%20PSYOP%20(CUI)/MISO/SOPs%20and%20Guides.one" target="_blank" rel="noreferrer">Editing on Intellipedia</a>):</p><p><strong>TAAW supporting MISO Series: <em>SERIES NAME</em> (<em>COUNTRY NAME</em>).</strong></p><h3 id="step-4-add-source-documentation-link" tabindex="-1">Step 4: Add Source Documentation Link <a class="header-anchor" href="#step-4-add-source-documentation-link" aria-label="Permalink to &quot;Step 4: Add Source Documentation Link&quot;">​</a></h3><p>Hit enter and in paragraph font, provide a link to source documentation:</p><p>&quot;Link to <em>Series Name</em> (<em>COUNTRY ABBREVIATION</em>) here.&quot;</p><p><em>We will come back to this at the end.</em></p><h3 id="step-5-save-the-page" tabindex="-1">Step 5: Save the Page <a class="header-anchor" href="#step-5-save-the-page" aria-label="Permalink to &quot;Step 5: Save the Page&quot;">​</a></h3><p>Click save page to create the page (others can now edit after this action).</p><ul><li>In the window that populates, select the correct classifications for each section.</li><li>Write a brief description summarizing the changes made in the summary box provided at the bottom.</li><li>Click OK.</li><li>Now click edit in the top right below the username.</li></ul><h3 id="step-6-set-classification" tabindex="-1">Step 6: Set Classification <a class="header-anchor" href="#step-6-set-classification" aria-label="Permalink to &quot;Step 6: Set Classification&quot;">​</a></h3><ol><li>Click the classification to the left of the title to change it to the proper classification if needed.</li><li>Click the classification banner above/below the page content.</li><li>Click the proper classification. <ul><li>If the proper caveat is not listed, click add/edit/delete while highlighting the classification.</li><li>Go to the dissemination tab and select the proper classification caveat (this is the overall classification of the document).</li><li>Scroll down and click OK.</li><li>Then click Apply.</li></ul></li></ol><h3 id="step-7-add-miso-series-header-data" tabindex="-1">Step 7: Add MISO Series Header Data <a class="header-anchor" href="#step-7-add-miso-series-header-data" aria-label="Permalink to &quot;Step 7: Add MISO Series Header Data&quot;">​</a></h3><p>Write &quot;MISO Series Header Data&quot; (Sub-heading 3).</p><ul><li>Underneath that, write the header data (MO, SMO, TA, RTA) (paragraph font).</li><li>Ensure that sources are included at the end of each line if needed.</li><li>Ensure that proper classification is included formatted as such:</li></ul><p><strong>MO: (U//FOUO) MO: <em>MO definition here</em> (<em>Source and MO</em>).</strong></p><ul><li>Link the source to the source page on Intellipedia if it exists.</li></ul><h3 id="step-8-add-content-sections-achievability-refined-assessment-criteria" tabindex="-1">Step 8: Add Content Sections (Achievability - Refined Assessment Criteria) <a class="header-anchor" href="#step-8-add-content-sections-achievability-refined-assessment-criteria" aria-label="Permalink to &quot;Step 8: Add Content Sections (Achievability - Refined Assessment Criteria)&quot;">​</a></h3><p>For the next sections:</p><ul><li>Use <strong>Heading</strong> for each major section (e.g., Conditions or Accessibility).</li><li>Use <strong>Sub-heading 2</strong> for second-level indented information bullets. <ul><li>Supporting information should be in paragraph font.</li></ul></li><li>Use <strong>Sub-heading 3</strong> for third-level indented information bullets. <ul><li>Supporting information should be in paragraph font.</li></ul></li><li>To insert pictures into sections (e.g., Symbols), see <a href="https://socom.sharepoint-mil.us/sites/socsouth-j3-jedpsyop/SiteAssets/SOCSOUTH%20J39%20PSYOP%20(CUI)/MISO/SOPs%20and%20Guides.one" target="_blank" rel="noreferrer">Editing on Intellipedia</a>.</li></ul><h3 id="step-9-add-references-section" tabindex="-1">Step 9: Add References Section <a class="header-anchor" href="#step-9-add-references-section" aria-label="Permalink to &quot;Step 9: Add References Section&quot;">​</a></h3><p>On a new line, write &quot;References&quot; (Heading font). See <a href="https://socom.sharepoint-mil.us/sites/socsouth-j3-jedpsyop/SiteAssets/SOCSOUTH%20J39%20PSYOP%20(CUI)/MISO/SOPs%20and%20Guides.one" target="_blank" rel="noreferrer">Citations in Intellipedia</a>.</p><ul><li>Create a numbered list by typing &quot;1.&quot; and then hitting the space bar to format it.</li><li>Start the reference with the format: <ul><li>(Classification letter) - <em>Name of the reference goes here</em> <em>Specific paragraph and line numbers go here</em>.</li></ul></li><li>Link the reference title to the reference document using the techniques from earlier in the workflow.</li></ul><p><strong>To link a reference:</strong></p><ol><li>Highlight the title of the reference.</li><li>Click link in the toolbar and then link.</li><li>Click External Site and copy/paste the URL of the source document from where you found it on the portal or the website that it was found on.</li></ol><h3 id="step-10-create-footnotes" tabindex="-1">Step 10: Create Footnotes <a class="header-anchor" href="#step-10-create-footnotes" aria-label="Permalink to &quot;Step 10: Create Footnotes&quot;">​</a></h3><ol><li>Highlight the word here.</li><li>Click link button (looks like two chain links) in the toolbar and then link.</li><li>Click OK Got it.</li><li>Click External Site and copy/paste the URL of the TAAW into the text bar. <ul><li>This should be the URL from where the TAAW is officially kept in the Portal.</li><li>(Pending or approved, this link will be updated as needed).</li></ul></li></ol><h3 id="step-11-final-save" tabindex="-1">Step 11: Final Save <a class="header-anchor" href="#step-11-final-save" aria-label="Permalink to &quot;Step 11: Final Save&quot;">​</a></h3><ol><li>Click done.</li><li>Hit save in the top right to create the page. <ul><li>Write a brief description summarizing the changes that you have made in the summary box that is provided at the bottom.</li><li>Click Save changes in the top right to save.</li></ul></li></ol><h3 id="step-12-link-to-main-page" tabindex="-1">Step 12: Link to Main Page <a class="header-anchor" href="#step-12-link-to-main-page" aria-label="Permalink to &quot;Step 12: Link to Main Page&quot;">​</a></h3><p>Once finished, go to <a href="https://socom.sharepoint-mil.us/sites/socsouth-j3-jedpsyop/SiteAssets/SOCSOUTH%20J39%20PSYOP%20(CUI)/MISO/SOPs%20and%20Guides.one" target="_blank" rel="noreferrer">Linking an Intellipedia page to a main page</a> to link this page to the 1st POB consolidated knowledge on Intellipedia.</p><h2 id="optional-add-links-section" tabindex="-1">Optional: Add Links Section <a class="header-anchor" href="#optional-add-links-section" aria-label="Permalink to &quot;Optional: Add Links Section&quot;">​</a></h2><p><em>This is not required but may be needed.</em></p><p>On a new line, write &quot;Links&quot; (Heading font).</p><ul><li>Provide links to all cross-referenced information in Intellipedia.</li><li>Create a numbered list by typing &quot;1.&quot; The format should look as follows: <ul><li>(Classification letter) - <em>LINK TITLE GOES HERE</em>.</li></ul></li><li>Link the phrase to the other existing pages using techniques from earlier in the workflow.</li></ul><p><strong>To link to another Intellipedia page:</strong></p><ol><li>Highlight the title of the reference.</li><li>Click link in the toolbar and then link.</li><li>Click Intellipedia and type the page that you wish to reference in the search bar and click it.</li></ol><h2 id="notes-for-refinement" tabindex="-1">Notes for Refinement <a class="header-anchor" href="#notes-for-refinement" aria-label="Permalink to &quot;Notes for Refinement&quot;">​</a></h2><ul><li>Add footnotes after adding the sources.</li></ul>',47)])])}const f=t(o,[["render",l]]);export{u as __pageData,f as default};
